window.__finlexDocLoaded(180,{"id":180,"articles":[{"id":4482,"no":"第一条","heading":"","text":"为了规范注册会计师在实施审计程序时使用审计抽样，制定本准则。","seq":0,"links":[{"doc_id":140,"tier":"L3","score":64,"rel_kind":"cites","target_seq":7,"target_art_no":"第8项","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1314号——审计抽样（2010年11月1日修订）》"}]},{"id":4483,"no":"第二条","heading":"","text":"《中国注册会计师审计准则第1301号——审计证据》要求注册会计师设计和实施审计程序，获取充分、适当的审计证据，以得出合理的结论，作为形成审计意见的基础。该准则还要求注册会计师确定用以选取测试项目的方法能够有效实现审计程序的目的，审计抽样是其中的一种方法。","seq":1,"links":[{"doc_id":176,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1301号——审计证据（2022年12月22日修订）》"}]},{"id":4484,"no":"第三条","heading":"","text":"本准则作为对《中国注册会计师审计准则第1301号——审计证据》的补充，规范了注册会计师在设计和选择审计样本以实施控制测试和细节测试，以及评价样本结果时对统计抽样和非统计抽样的使用。 ## 第二章 定义","seq":2,"links":[{"doc_id":176,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1301号——审计证据（2022年12月22日修订）》"}]},{"id":4485,"no":"第四条","heading":"","text":"审计抽样（即抽样），是指注册会计师对具有审计相关性的总体中低于百分之百的项目实施审计程序，使所有抽样单元都有被选取的机会，为注册会计师针对整个总体得出结论提供合理基础。","seq":3},{"id":4486,"no":"第五条","heading":"","text":"总体，是指注册会计师从中选取样本并期望据此得出结论的整个数据集合。","seq":4},{"id":4487,"no":"第六条","heading":"","text":"抽样单元，是指构成总体的个体项目。","seq":5},{"id":4488,"no":"第七条","heading":"","text":"统计抽样，是指同时具备下列特征的抽样方法： **（一）随机选取样本项目；** **（二）运用概率论评价样本结果，包括计量抽样风险。** 不同时具备前款提及的两个特征的抽样方法为非统计抽样。","seq":6},{"id":4489,"no":"第八条","heading":"","text":"抽样风险，是指注册会计师根据样本得出的结论，可能不同于如果对整个总体实施与样本相同的审计程序得出的结论的风险。抽样风险可能导致两种类型的错误结论： （一）在实施控制测试时，注册会计师推断的控制有效性高于其实际有效性；或在实施细节测试时，注册会计师推断某一重大错报不存在而实际上存在。注册会计师主要关注这类错误结论，原因是其影响审计效果，非常有可能导致发表不恰当的审计意见。 （二）在实施控制测试时，注册会计师推断的控制有效性低于其实际有效性；或在实施细节测试时，注册会计师推断某一重大错报存在而实际上不存在。这类错误结论影响审计效率，原因是其通常导致注册会计师实施额外的工作，以证实初始结论是错误的。","seq":7},{"id":4490,"no":"第九条","heading":"","text":"非抽样风险，是指注册会计师由于任何与抽样风险无关的原因而得出错误结论的风险。","seq":8},{"id":4491,"no":"第十条","heading":"","text":"异常误差，是指对总体中的错报或偏差明显不具有代表性的错报或偏差。","seq":9},{"id":4492,"no":"第十一条","heading":"","text":"分层，是指将总体划分为多个子总体的过程，每个子总体由一组具有相同特征（通常为货币金额）的抽样单元组成。","seq":10},{"id":4493,"no":"第十二条","heading":"","text":"可容忍错报，是指注册会计师设定的货币金额，注册会计师试图对总体中的实际错报不超过该货币金额获取适当水平的保证。","seq":11},{"id":4494,"no":"第十三条","heading":"","text":"可容忍偏差率，是指注册会计师设定的偏离规定的内部控制程序的比率，注册会计师试图对总体中的实际偏差率不超过该比率获取适当水平的保证。 ## 第三章 目标","seq":12},{"id":4495,"no":"第十四条","heading":"","text":"在使用审计抽样时，注册会计师的目标是，为得出有关抽样总体的结论提供合理的基础。 ## 第四章 要求 ### 第一节 样本设计、样本规模和选取测试项目","seq":13},{"id":4496,"no":"第十五条","heading":"","text":"在设计审计样本时，注册会计师应当考虑审计程序的目的和抽样总体的特征。","seq":14},{"id":4497,"no":"第十六条","heading":"","text":"注册会计师应当确定足够的样本规模，以将抽样风险降至可接受的低水平。","seq":15},{"id":4498,"no":"第十七条","heading":"","text":"注册会计师在选取样本项目时，应当使总体中的每个抽样单元都有被选取的机会。 ### 第二节 实施审计程序","seq":16},{"id":4499,"no":"第十八条","heading":"","text":"注册会计师应当针对选取的每个项目，实施适合具体目的的审计程序。","seq":17},{"id":4500,"no":"第十九条","heading":"","text":"如果审计程序不适用于选取的项目，注册会计师应当针对替代项目实施该审计程序。","seq":18},{"id":4501,"no":"第二十条","heading":"","text":"如果未能对某个选取的项目实施设计的审计程序或适当的替代程序，注册会计师应当将该项目视为控制测试中对规定的控制的一项偏差，或细节测试中的一项错报。 ### 第三节 偏差和错报的性质与原因","seq":19},{"id":4502,"no":"第二十一条","heading":"","text":"注册会计师应当调查识别出的所有偏差或错报的性质和原因，并评价其对审计程序的目的和审计的其他方面可能产生的影响。","seq":20},{"id":4503,"no":"第二十二条","heading":"","text":"在极其特殊的情况下，如果认为样本中发现的某项偏差或错报是异常误差，注册会计师应当对该项偏差或错报对总体不具有代表性获取高度保证。在获取这种高度保证时，注册会计师应当实施追加的审计程序，获取充分、适当的审计证据，以确定该项偏差或错报不影响总体的其余部分。 ### 第四节 推断错报","seq":21},{"id":4504,"no":"第二十三条","heading":"","text":"当实施细节测试时，注册会计师应当根据样本中发现的错报推断总体错报。 ### 第五节 评价审计抽样结果","seq":22},{"id":4505,"no":"第二十四条","heading":"","text":"注册会计师应当对下列方面进行评价： **（一）样本结果；** （二）使用审计抽样是否已为注册会计师针对所测试的总体得出的结论提供合理基础。 ## 第五章 附则","seq":23},{"id":4506,"no":"第二十五条","heading":"","text":"本准则自2012年1月1日起施行。","seq":24}]});
